CREATE TABLE cache_attempt (attempt_id TEXT PRIMARY KEY, project TEXT NOT NULL, trust TEXT NOT NULL, protection TEXT NOT NULL, head_repo TEXT NOT NULL DEFAULT '', pr TEXT NOT NULL DEFAULT '', secrets_declared INTEGER NOT NULL CHECK(secrets_declared IN (0,1)), private_deps INTEGER NOT NULL CHECK(private_deps IN (0,1)), passed INTEGER NOT NULL DEFAULT 0 CHECK(passed IN (0,1)), recorded_at INTEGER NOT NULL);
CREATE TABLE cache_planned (attempt_id TEXT NOT NULL REFERENCES cache_attempt(attempt_id) ON DELETE CASCADE, cache_key TEXT NOT NULL, PRIMARY KEY(attempt_id,cache_key));
CREATE TABLE cache_entry (cache_key TEXT PRIMARY KEY, namespace BLOB NOT NULL, spec TEXT NOT NULL, attempt_id TEXT NOT NULL, epoch INTEGER NOT NULL, source_trust TEXT NOT NULL, secrets_received INTEGER NOT NULL CHECK(secrets_received IN (0,1)), private_deps INTEGER NOT NULL CHECK(private_deps IN (0,1)), scanned_clean INTEGER NOT NULL CHECK(scanned_clean IN (0,1)), bytes INTEGER NOT NULL CHECK(bytes>=0), created_at INTEGER NOT NULL, last_used_at INTEGER NOT NULL);
CREATE INDEX cache_entry_lru ON cache_entry(last_used_at, cache_key);
CREATE TABLE cache_entry_blob (cache_key TEXT NOT NULL REFERENCES cache_entry(cache_key) ON DELETE CASCADE, path TEXT NOT NULL, sha256 TEXT NOT NULL, size INTEGER NOT NULL CHECK(size>=0), PRIMARY KEY(cache_key,path));
CREATE TABLE cache_use (id INTEGER PRIMARY KEY AUTOINCREMENT, attempt_id TEXT NOT NULL, spec TEXT NOT NULL, cache_key TEXT NOT NULL, result TEXT NOT NULL CHECK(result IN ('hit','miss','disabled','readonly','denied','refused')), bytes INTEGER NOT NULL CHECK(bytes>=0), ms INTEGER NOT NULL CHECK(ms>=0), ts INTEGER NOT NULL);
CREATE INDEX cache_use_ts ON cache_use(ts);
CREATE INDEX cache_use_attempt ON cache_use(attempt_id, id);
